-- Dataset: cx_nps
-- Title: NPS 13-week window
-- Tab: CX
-- Connector: Google Cloud BigQuery  Tool: execute_sql_readonly
-- Project: petcircle-data-ca
-- Labels: null
-- Description: One-row 13-week NPS summary with bands, last four weeks, reporting and prior week, against a target of 80 held in this query because the warehouse has no NPS target. Also carries the reporting week on its own (NPS, bands, vs last week, target and the prior 12 weeks). Reads customer__customer_review, reference__calendar_4_4_5_week.

WITH wk AS (SELECT week_end_date AS we, DATE_SUB(week_end_date, INTERVAL 90 DAY) AS ws FROM `petcircle-warehouse-cloud.business_layer.reference__calendar_4_4_5_week` WHERE is_latest_merch_complete_week = TRUE), r AS (SELECT DATE_TRUNC(v.review_date, WEEK(MONDAY)) AS week_start, v.review_id, v.net_promoter_count AS np, v.review_count_promoter AS pr, v.review_count_neutral AS pa, v.review_count_detractor AS de, v.review_text, v.customer_review_order_mapping[SAFE_OFFSET(0)].order_id AS oid FROM `petcircle-warehouse-cloud.business_layer.customer__customer_review` v CROSS JOIN wk WHERE v.review_date BETWEEN wk.ws AND wk.we), tot AS (SELECT COUNT(*) AS n, COUNTIF(LENGTH(TRIM(review_text)) >= 3) AS comments, SUM(np) AS np, SUM(pr) AS pr, SUM(pa) AS pa, SUM(de) AS de FROM r), l4 AS (SELECT ROUND(SUM(np) / COUNT(*) * 100, 1) AS nps FROM r CROSS JOIN wk WHERE r.week_start > DATE_SUB(DATE_TRUNC(wk.we, WEEK(MONDAY)), INTERVAL 28 DAY)), tw AS (SELECT COUNT(*) AS n, ROUND(SUM(np) / COUNT(*) * 100, 1) AS nps, SUM(pr) AS pr, SUM(pa) AS pa, SUM(de) AS de FROM r CROSS JOIN wk WHERE r.week_start = DATE_TRUNC(wk.we, WEEK(MONDAY))), p12 AS (SELECT COUNT(*) AS n, ROUND(SUM(np) / COUNT(*) * 100, 1) AS nps FROM r CROSS JOIN wk WHERE r.week_start BETWEEN DATE_SUB(DATE_TRUNC(wk.we, WEEK(MONDAY)), INTERVAL 84 DAY) AND DATE_SUB(DATE_TRUNC(wk.we, WEEK(MONDAY)), INTERVAL 7 DAY)), lw AS (SELECT COUNT(*) AS n, ROUND(SUM(np) / COUNT(*) * 100, 1) AS nps FROM r CROSS JOIN wk WHERE r.week_start = DATE_SUB(DATE_TRUNC(wk.we, WEEK(MONDAY)), INTERVAL 7 DAY)) SELECT CAST(wk.ws AS STRING) AS window_start, CAST(wk.we AS STRING) AS window_end, 13 AS weeks, tot.n AS responses, tot.comments AS comments, ROUND(tot.np / tot.n * 100, 1) AS nps, tot.pr AS promoters, tot.pa AS passives, tot.de AS detractors, ROUND(tot.pr / tot.n * 100, 1) AS promoter_pct, ROUND(tot.pa / tot.n * 100, 1) AS passive_pct, ROUND(tot.de / tot.n * 100, 1) AS detractor_pct, l4.nps AS last4_nps, ROUND(l4.nps - tot.np / tot.n * 100, 1) AS last4_vs_window, 80.0 AS target, ROUND(tot.np / tot.n * 100 - 80.0, 1) AS nps_vs_target, tw.nps AS tw_nps, tw.n AS tw_n, lw.nps AS lw_nps, lw.n AS lw_n, tw.pr AS tw_promoters, tw.pa AS tw_passives, tw.de AS tw_detractors, ROUND(tw.pr / tw.n * 100, 1) AS tw_promoter_pct, ROUND(tw.pa / tw.n * 100, 1) AS tw_passive_pct, ROUND(tw.de / tw.n * 100, 1) AS tw_detractor_pct, ROUND(tw.nps - 80.0, 1) AS tw_vs_target, ROUND(tw.nps - lw.nps, 1) AS tw_vs_lw, p12.nps AS l12_nps, p12.n AS l12_n, ROUND(tw.nps - p12.nps, 1) AS tw_vs_l12, CAST(DATE_TRUNC(wk.we, WEEK(MONDAY)) AS STRING) AS tw_start, CAST(wk.we AS STRING) AS week_end FROM wk, tot, l4, tw, lw, p12
